        wy = max(wy, 2.2)
    if 20.5 <= x <= G2_X + 1.0 and y < 1.85:
        wx, wy = x + 0.3, 2.5

    # Calculate direction vector to waypoint
    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx * dx + dy * dy)

