        if y < 1.8:
            fy += 150.0
        elif y > 3.0:
            fy -= 150.0

    # Apply additional thrust to maintain forward speed
    vel = sandbox.get_craft_velocity()
    if vel is not None:
        vx, vy = vel
        if vx < MIN_FORWARD_SPEED:
            fx += (MIN_FORWARD_SPEED - vx) * 5.0  # Adjust this factor as needed

    # Apply wind compensation
    if WIND_LO <= x <= WIND_HI:
        wind_fy = WIND_AMP * math.sin(WIND_OMEGA * step_idx)
        fy -= wind_fy

    # Apply slip compensation
    if SLIP_LO <= x <= SLIP_HI:
