    # Apply additional thrust in specific regions
    if y < 1.4:
        fy += 100.0
    if x < G1_X + 1.0 and y < 1.1:
        fy += min(30.0, (1.2 - y) * 40.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        fy += 110.0
    if x > 25.0 and y < 3.0:
        fy += 120.0

    # Cap thrust to prevent exceeding maximum allowed
    total = math.sqrt(fx * fx + fy * fy)
    cap = thrust_mag * 2.5
    if y < 1.4:
        cap = max(cap, 180.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
